WITH valid_departments AS (SELECT * FROM departments WHERE budget BETWEEN 1597000 AND 3697000), summary AS (SELECT location, CASE WHEN budget >= 4246000 THEN 'high' WHEN budget >= 950000 THEN 'mid' ELSE 'low' END AS budget_bucket, MIN(budget) AS min_budget FROM valid_departments GROUP BY location, CASE WHEN budget >= 4246000 THEN 'high' WHEN budget >= 950000 THEN 'mid' ELSE 'low' END) SELECT location, budget_bucket FROM summary ORDER BY location DESC, budget_bucket LIMIT 20;
